export default "<!doctype html>\n<html lang=\"de-CH\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"referrer\" content=\"same-origin\"><title>Jonas · Website Analytics</title>\n<style>\n:root{color-scheme:light dark;--bg:#f3f5f4;--panel:#fff;--ink:#182c27;--muted:#5e7169;--line:#dce5e0;--accent:#166a54;--soft:#e9f3ed}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:30px 24px}header{display:flex;justify-content:space-between;align-items:start;gap:24px}h1{font-size:clamp(26px,4vw,40px);letter-spacing:-1px;margin:5px 0}h2{font-size:19px;margin:0 0 16px}p{margin:6px 0 14px}.eyebrow{font:12px ui-monospace,monospace;text-transform:uppercase;letter-spacing:2px;color:var(--accent)}.muted,small{color:var(--muted)}.panel,.metric{min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:22px}.toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:16px;margin:25px 0}.toolbar label{display:grid;gap:5px;font-size:13px}select,button,input{font:inherit}button,select,.file{background:var(--panel);border:1px solid var(--line);padding:9px 13px;border-radius:8px;color:var(--ink)}button,.file{cursor:pointer}button:hover{border-color:var(--accent)}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.file{display:inline-block}input[type=file]{max-width:250px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:20px 0}.metric .value{font-size:34px;font-weight:650;letter-spacing:-1px}.metric p{font-size:13px;margin:4px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:18px 0}.wide{grid-column:1/-1}.bars{display:grid;gap:12px}.barlabel{overflow-wrap:anywhere;display:flex;justify-content:space-between;font-size:13px;gap:12px}.track{height:7px;background:var(--soft);border-radius:10px;margin-top:5px;overflow:hidden}.fill{height:100%;background:var(--accent);border-radius:10px}table{overflow-wrap:anywhere;border-collapse:collapse;width:100%;font-size:13px}th,td{padding:9px 6px;text-align:left;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:500}td:last-child,th:last-child{text-align:right}.scroll{overflow:auto;max-height:340px}.chart{height:200px;display:flex;align-items:end;gap:3px;padding:15px 0 25px;overflow-x:auto}.day{display:flex;flex:1;min-width:4px;height:100%;align-items:end;position:relative}.day div{background:var(--accent);width:100%;min-height:1px;border-radius:3px 3px 0 0}.day span{position:absolute;bottom:-24px;font:10px ui-monospace,monospace;white-space:nowrap}.notice{border-left:3px solid var(--accent);padding:12px 16px;background:var(--soft);border-radius:4px;margin:16px 0}.error{color:#b03535}.heat{display:grid;grid-template-columns:35px repeat(24,minmax(10px,1fr));gap:3px;font-size:10px}.cell{height:20px;background:var(--accent);border-radius:3px}.heatlabel{color:var(--muted)}.links a{color:var(--accent);margin-right:14px}footer{font-size:12px;margin-top:24px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:760px){main{padding:20px 14px}.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.wide{grid-column:auto}header{display:block}.panel{padding:16px}.metric .value{font-size:27px}}@media(prefers-color-scheme:dark){:root{--bg:#111c18;--panel:#192720;--ink:#e3eee7;--muted:#a4b8ab;--line:#31463a;--accent:#7bd6ab;--soft:#233e2e}}\n</style></head><body><main>\n<header><div><div class=\"eyebrow\">Jonas Bader · Analytics</div><h1>Was wird wirklich genutzt?</h1><p class=\"muted\">Portfolio, GreenRoute und Projekt Transparenz auf einen Blick.</p></div><div><label class=\"file\">Bericht laden <input id=\"file\" type=\"file\" accept=\"application/json,.json\"></label><p><button id=\"example\" type=\"button\">Beispieldaten ansehen</button></p></div></header>\n<div id=\"status\" role=\"status\" class=\"notice\">Verbindung zur geschützten Live-Ansicht wird geprüft … <a id=\"live-link\" href=\"https://jonas-portfolio-analytics.jonas-bader-analytics.workers.dev/dashboard\">Live-Dashboard öffnen</a> · alternativ einen gespeicherten Bericht laden.</div>\n<div class=\"toolbar\"><label id=\"live-days\" hidden>Zeitraum<select id=\"days\"><option value=\"7\">7 Tage</option><option value=\"30\" selected>30 Tage</option><option value=\"90\">90 Tage</option><option value=\"180\">180 Tage</option></select></label><button id=\"refresh\" type=\"button\" hidden>Jetzt aktualisieren</button><form id=\"logout\" action=\"/dashboard/logout\" method=\"post\" hidden><button>Abmelden</button></form><label>Website<select id=\"site\"><option value=\"all\">Alle Websites</option><option value=\"portfolio\">Portfolio</option><option value=\"greenroute\">GreenRoute</option><option value=\"transparenz\">Projekt Transparenz</option></select></label><label>Tagesverlauf<select id=\"range\"><option value=\"all\">Ganzer geladener Zeitraum</option><option value=\"7\">Letzte 7 Tage im Bericht</option><option value=\"30\">Letzte 30 Tage im Bericht</option></select></label><button id=\"csv\" type=\"button\" disabled>Tageswerte als CSV</button><button id=\"json\" type=\"button\" disabled>Bericht als JSON</button></div>\n<div id=\"report\" hidden>\n<p id=\"period\" class=\"muted\"></p><div id=\"metrics\" class=\"metrics\"></div><div id=\"insights\" class=\"notice\"></div>\n<div class=\"grid\"><section class=\"panel wide\"><h2>Seitenaufrufe im Zeitverlauf</h2><div id=\"trend\" class=\"chart\" role=\"img\" aria-label=\"Tägliche Seitenaufrufe\"></div><details><summary>Tageswerte als Tabelle</summary><div id=\"daily\" class=\"scroll\"></div></details></section>\n<section class=\"panel\"><h2>Websites im Vergleich</h2><div id=\"sites\"></div><p class=\"muted\"><small>Aktive Sekunden je Aufruf sind ein Näherungswert, keine Sitzungsdauer.</small></p></section>\n<section class=\"panel\"><h2>Woher kommen Aufrufe?</h2><div id=\"sources\" class=\"bars\"></div><p class=\"muted\"><small>UTM-Quelle oder grobe Herkunftskategorie. «Direkt / unbekannt» enthält auch nicht erkennbare Quellen.</small></p></section>\n<section class=\"panel\"><h2>Welche Links werden genutzt?</h2><div id=\"clicks\" class=\"scroll\"></div></section><section class=\"panel\"><h2>Welche Funktionen werden genutzt?</h2><div id=\"features\" class=\"scroll\"></div></section>\n<section class=\"panel\"><h2>Lesefortschritt</h2><div id=\"scroll\" class=\"bars\"></div><p class=\"muted\"><small>Jede Schwelle höchstens einmal pro Seitenladung. Keine Besucherquote; kurze Seiten werden nicht erfasst.</small></p></section>\n<section class=\"panel\"><h2>Transparenz: Seitentypen</h2><div id=\"pages\" class=\"bars\"></div><p class=\"muted\"><small>Nur Übersicht, Analyse, Methodik und Quellen; keine Fonds- oder Unternehmenskennungen.</small></p></section>\n<section class=\"panel\"><h2>Länder</h2><div id=\"countries\" class=\"bars\"></div></section><section class=\"panel\"><h2>Geräte und Browser</h2><div id=\"devices\" class=\"bars\"></div></section>\n<section class=\"panel\"><h2>Regionen und Städte · ungefähr</h2><div id=\"regions\" class=\"scroll\"></div></section><section class=\"panel\"><h2>Wann wird die Website geöffnet?</h2><div class=\"scroll\"><div id=\"hours\" class=\"heat\"></div></div><p class=\"muted\"><small>Wochentag und Stunde in UTC. Dunklere Felder bedeuten mehr Aufrufe.</small></p></section></div>\n<p class=\"links\"><a href=\"https://jonasbader7.github.io/Portfoliopage/\" target=\"_blank\" rel=\"noopener noreferrer\">Portfolio ↗</a><a href=\"https://jonasbader7.github.io/GreenRoute/\" target=\"_blank\" rel=\"noopener noreferrer\">GreenRoute ↗</a><a href=\"https://jonasbader7.github.io/Projekt-Transparenz/\" target=\"_blank\" rel=\"noopener noreferrer\">Transparenz-Demo ↗</a></p>\n</div><footer>Gezählt werden Events und Aufrufe, keine eindeutigen Personen. Blocker, DNT und GPC begrenzen die Messung. Neue Nutzungsmerkmale entstehen erst ab dem aktualisierten Client. Historische BORS-Zähler werden als GreenRoute dargestellt. Dieser Bericht enthält keine IP-Sicherheitslogs. Die Live-Ansicht lädt Aggregate ausschliesslich vom geschützten Analytics-Worker; es werden keine Statistikdaten an Dritte gesendet.</footer>\n</main><script id=\"report-data\" type=\"application/json\">null</script><script>\n'use strict';\nconst $=id=>document.getElementById(id), fmt=n=>new Intl.NumberFormat('de-CH',{maximumFractionDigits:1}).format(n||0);\nconst names={portfolio:'Portfolio',greenroute:'GreenRoute',transparenz:'Projekt Transparenz'}, normal=s=>s==='bors'?'greenroute':s;\nlet data=null,isExample=false;\nconst live=location.pathname==='/dashboard'&&location.protocol!=='file:';\nlet pending=null;\nasync function refreshLive(){\n  if(!live||document.visibilityState==='hidden')return;\n  if(pending)pending.abort();\n  const controller=new AbortController();pending=controller;\n  $('status').classList.remove('error');$('status').textContent='Aktuelle Statistik wird geladen …';\n  try{\n    const response=await fetch('/admin/summary?days='+encodeURIComponent($('days').value)+'&site='+encodeURIComponent($('site').value),{credentials:'same-origin',cache:'no-store',signal:controller.signal});\n    if(response.status===401){$('report').hidden=true;location.replace('/dashboard');return;}\n    if(!response.ok)throw Error('Statistik momentan nicht erreichbar ('+response.status+'). Erneut versuchen.');\n    const report=await response.json();if(pending!==controller)return;load(report);\n  }catch(e){if(e.name!=='AbortError'){$('status').textContent=e.message+(data?' Die angezeigten Werte stammen vom letzten erfolgreichen Abruf.':'');$('status').classList.add('error');}}\n  finally{if(pending===controller)pending=null;}\n}\nconst empty='Noch keine Daten in dieser Auswahl.';\nfunction node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}\nfunction group(rows,key){const out=new Map();for(const r of rows){const k=key(r);out.set(k,(out.get(k)||0)+Number(r.hits||0));}return [...out].map(([label,hits])=>({label,hits})).sort((a,b)=>b.hits-a.hits);}\nfunction table(id,headers,rows){const root=$(id);root.replaceChildren();if(!rows.length){root.textContent=empty;return;}const t=node('table'),head=node('thead'),hr=node('tr');headers.forEach(h=>hr.append(node('th',h)));head.append(hr);t.append(head);const body=node('tbody');rows.forEach(row=>{const tr=node('tr');row.forEach(c=>tr.append(node('td',String(c))));body.append(tr);});t.append(body);root.append(t);}\nfunction bars(id,rows){const root=$(id);root.replaceChildren();if(!rows.length){root.textContent=empty;return;}const max=Math.max(1,...rows.map(r=>r.hits));rows.slice(0,15).forEach(r=>{const wrap=node('div'),label=node('div',undefined,'barlabel');label.append(node('span',r.label),node('strong',fmt(r.hits)));const track=node('div',undefined,'track'),fill=node('div',undefined,'fill');fill.style.width=(r.hits/max*100)+'%';track.append(fill);wrap.append(label,track);root.append(wrap);});}\nfunction validate(v){if(!v||typeof v!=='object'||!Array.isArray(v.totals)||!Array.isArray(v.daily))throw Error('Kein gültiger Analytics-Bericht: totals und daily fehlen.');for(const k of ['totals','daily','previous','countries','regions','devices','sources','clicks','hours']){if(v[k]!==undefined&&!Array.isArray(v[k]))throw Error('Ungültige Tabelle: '+k);for(const r of v[k]||[])if(!r||typeof r!=='object'||!Number.isFinite(Number(r.hits))||Number(r.hits)<0||('seconds'in r&&(!Number.isFinite(Number(r.seconds))||Number(r.seconds)<0)))throw Error('Ungültige Zahlen in '+k);}return v;}\nfunction load(v,example=false){try{data=validate(v);isExample=example;$('site').value=['all',...Object.keys(names)].includes(v.site)?v.site:'all';$('range').value='all';render();}catch(e){$('status').textContent=e.message;$('status').classList.add('error');}}\nfunction filtered(key){const rows=data[key]||[],s=$('site').value;return rows.filter(r=>s==='all'||normal(r.site)===s);}\nfunction dailyRows(){let rows=filtered('daily');const n=$('range').value;if(n!=='all'){const end=new Date(data.until||data.generatedAt||new Date().toISOString());const cutoff=new Date(end);cutoff.setUTCDate(cutoff.getUTCDate()-Number(n));rows=rows.filter(r=>r.day>=cutoff.toISOString().slice(0,10));}return rows;}\nfunction counts(rows,event,field='hits'){return rows.filter(r=>r.event===event).reduce((sum,r)=>sum+Number(r[field]||0),0);}\nfunction detail(s){return String(s||'').replace(/^github:BORS$/,'github:GreenRoute').replace(/^bors-demo$/,'GreenRoute-Demo').replace(/^github:/,'GitHub / ').replace(/^demo:details_/,'Projektdetails: ').replace(/^demo:greenroute_preview$/,'GreenRoute-Vorschau gestartet').replace(/^view:language_/,'Sprache: ');}\nfunction render(){if(!data)return;$('report').hidden=false;$('csv').disabled=false;$('json').disabled=false;$('status').classList.remove('error');$('status').textContent=isExample?'BEISPIELDATEN – frei erfundene Zahlen, keine echten Besucherstatistiken.':live?'Live verbunden · automatischer Abruf alle 60 Sekunden · Auswertung bis zur letzten vollen UTC-Stunde.':'Privater Bericht geladen. Für automatische Aktualisierung die geschützte Live-Ansicht öffnen.';\nconst narrow=$('range').value!=='all',rows=filtered('totals'),views=counts(rows,'pageview'),clicks=counts(rows,'link_click'),secs=counts(rows,'engagement','seconds'),features=counts(rows,'feature_click');\n$('period').textContent=(data.since||'Beginn unbekannt')+' bis '+(data.until||data.generatedAt||'Ende unbekannt')+' · UTC · '+(narrow?'Zoom im Tagesverlauf; Kennzahlen und Detailtabellen zeigen den ganzen geladenen Zeitraum.':'Ganze geladene Periode.')+' · Erstellt: '+(data.generatedAt||'unbekannt');\n$('metrics').replaceChildren();const previous=filtered('previous'),canCompare=data.comparisonComplete===true;\n[['Seitenaufrufe',views,counts(previous,'pageview')],['Link-Klicks',clicks,counts(previous,'link_click')],['Funktionsereignisse',features,counts(previous,'feature_click')],['Aktive Sek. / Aufruf',views?secs/views:0,null]].forEach(([label,val,old])=>{const box=node('div',undefined,'metric');box.append(node('div',label,'muted'),node('div',fmt(val),'value'));box.append(node('p',old===null?'Vordergrundzeit / Seitenaufrufe':canCompare?(old?((val-old>=0?'+':'')+fmt((val-old)/old*100)+' % zur Vorperiode'):(val?'Vorperiode ohne Events':'Beide Perioden ohne Events')):'Vergleich nach Backend-Update / für vollständige Perioden bis 90 Tage'));$('metrics').append(box);});\nconst daily=group(dailyRows().filter(r=>r.event==='pageview'),r=>r.day);const byDay=new Map(daily.map(r=>[r.label,r.hits]));let start=data.since?.slice(0,10)||[...byDay.keys()].sort()[0],end=(data.until?new Date(new Date(data.until).getTime()-1).toISOString().slice(0,10):null)||[...byDay.keys()].sort().at(-1);const n=$('range').value;if(n!=='all'&&end){const d=new Date(end+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-Number(n));start=[start,d.toISOString().slice(0,10)].filter(Boolean).sort().at(-1);}const series=[];if(start&&end){for(let d=new Date(start+'T00:00:00Z'),i=0;d.toISOString().slice(0,10)<=end&&i<182;d.setUTCDate(d.getUTCDate()+1),i++){const day=d.toISOString().slice(0,10);series.push({day,hits:byDay.get(day)||0});}}\n$('trend').replaceChildren();const max=Math.max(1,...series.map(r=>r.hits));series.forEach((r,i)=>{const bar=node('div',undefined,'day');bar.title=r.day+': '+fmt(r.hits)+' Aufrufe';const fill=node('div');fill.style.height=Math.max(0.5,r.hits/max*100)+'%';bar.append(fill);if(i%Math.max(1,Math.ceil(series.length/8))===0)bar.append(node('span',r.day.slice(5)));$('trend').append(bar);});table('daily',['Tag UTC','Aufrufe'],series.map(r=>[r.day,fmt(r.hits)]));\nconst siteRows=Object.keys(names).filter(s=>$('site').value==='all'||$('site').value===s).map(s=>{const t=rows.filter(r=>normal(r.site)===s),v=counts(t,'pageview');return[names[s],fmt(v),fmt(counts(t,'link_click')),fmt(v?counts(t,'engagement','seconds')/v:0)];});table('sites',['Website','Aufrufe','Links','Sek. / Aufruf'],siteRows);\nconst links=group(filtered('clicks').filter(r=>r.event==='link_click'),r=>detail(r.detail)),fn=group(filtered('clicks').filter(r=>r.event==='feature_click'&&!/^view:(scroll_|page_)/.test(r.detail)),r=>detail(r.detail));table('clicks',['Link-Kategorie','Klicks'],links.map(r=>[r.label,fmt(r.hits)]));table('features',['Funktion','Events'],fn.map(r=>[r.label,fmt(r.hits)]));\nbars('sources',group(filtered('sources'),r=>r.source||'Direkt / unbekannt'));bars('countries',group(filtered('countries'),r=>r.country||'Unbekannt'));bars('devices',group(filtered('devices'),r=>(r.device||'unbekannt')+' · '+(r.browser||'unbekannt')));\nconst scroll=group(filtered('clicks').filter(r=>/^view:scroll_(25|50|75|100)$/.test(r.detail)),r=>r.detail.split('_').at(-1)+' % erreicht');scroll.sort((a,b)=>parseInt(a.label)-parseInt(b.label));bars('scroll',scroll);bars('pages',group(filtered('clicks').filter(r=>/^view:page_/.test(r.detail)),r=>r.detail.replace('view:page_','')));\ntable('regions',['Land','Region','Stadt ≈','Aufrufe'],group(filtered('regions'),r=>[r.country||'',r.region||'',r.city||''].join(' | ')).slice(0,50).map(r=>[...r.label.split(' | '),fmt(r.hits)]));\n$('hours').replaceChildren();const hourRows=data.hours||[];$('hours').style.display=hourRows.length&&($('site').value==='all'||data.site===$('site').value)?'grid':'block';if($('site').value!=='all'&&data.site!==$('site').value){$('hours').textContent='Für Stundenwerte einer Website den Bericht mit -Site neu laden.';}else if(hourRows.length){const maxH=Math.max(1,...hourRows.map(r=>r.hits));$('hours').append(node('span'));for(let h=0;h<24;h++)$('hours').append(node('span',h,'heatlabel'));['Mo','Di','Mi','Do','Fr','Sa','So'].forEach((day,index)=>{const weekday=(index+1)%7;$('hours').append(node('span',day,'heatlabel'));for(let h=0;h<24;h++){const hits=hourRows.filter(r=>Number(r.weekday)===weekday&&Number(r.hour)===h).reduce((a,r)=>a+Number(r.hits),0);const c=node('div',undefined,'cell');c.style.opacity=String(0.07+0.93*hits/maxH);c.title=day+' '+h+':00 UTC · '+fmt(hits)+' Aufrufe';$('hours').append(c);}});}else $('hours').textContent='Nach Backend-Update verfügbar.';\nconst src=group(filtered('sources'),r=>r.source||'Direkt / unbekannt')[0];$('insights').textContent=views?(links.length?'Meistgenutzter Link: '+links[0].label+' ('+fmt(links[0].hits)+' Klicks). ':'Noch keine Link-Klicks gemessen. ')+(src?'Stärkste Herkunftskategorie: '+src.label+'. ':'')+'Prüfe, ob die wichtigsten Projekte und Kontaktmöglichkeiten dort gut sichtbar sind. Klicks / Aufrufe sind keine Conversion-Rate einzelner Besucher.':'Noch keine Aufrufe in dieser Auswahl. Prüfe Zeitraum, Client-Konfiguration und letzte Bereitstellung.';\n}\nfunction download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const a=node('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\n$('file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10_000_000)throw Error('Datei ist zu gross (max. 10 MB).');load(JSON.parse(await f.text()));}catch(err){$('status').textContent=err.message;$('status').classList.add('error');}});\n$('site').addEventListener('change',()=>live?refreshLive():render());$('range').addEventListener('change',render);\n$('json').onclick=()=>download(JSON.stringify(data,null,2),'application/json','analytics-report.json');\n$('csv').onclick=()=>{const rows=dailyRows();const quote=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';download('\\uFEFF'+[['Tag UTC','Website','Event','Anzahl','Sekunden'],...rows.map(r=>[r.day,names[normal(r.site)]||normal(r.site),r.event,r.hits,r.seconds||0])].map(r=>r.map(quote).join(';')).join('\\r\\n'),'text/csv;charset=utf-8','analytics-daily.csv');};\n$('example').onclick=()=>{const totals=[],daily=[],clicks=[],sources=[],countries=[],devices=[];['portfolio','greenroute','transparenz'].forEach((site,i)=>{const hits=[240,130,65][i];totals.push({site,event:'pageview',hits},{site,event:'link_click',hits:Math.round(hits/5)},{site,event:'engagement',hits:50,seconds:hits*24},{site,event:'feature_click',hits:40});for(let d=1;d<=7;d++)daily.push({day:'2026-11-0'+d,site,event:'pageview',hits:Math.round(hits/7)+(d%3)});clicks.push({site,event:'link_click',detail:'github:GreenRoute',hits:18-i*5},{site,event:'feature_click',detail:'view:scroll_50',hits:25-i*7},{site,event:'feature_click',detail:'demo:details_greenroute',hits:12-i*3});sources.push({site,source:'github',hits:80-i*25},{site,source:'',hits:160-i*40});countries.push({site,country:'CH',hits:90-i*20});devices.push({site,device:'desktop',browser:'Firefox',hits:70-i*20});});clicks.push({site:'transparenz',event:'feature_click',detail:'view:page_analyse',hits:30});load({days:7,site:'all',since:'2026-11-01T00:00:00Z',until:'2026-11-08T00:00:00Z',generatedAt:'2026-11-08T00:00:00Z',totals,daily,clicks,sources,countries,devices,regions:[],hours:[],previous:[],comparisonComplete:false},true);};\ntry{const initial=JSON.parse($('report-data').textContent);if(initial)load(initial);}catch(e){$('status').textContent='Eingebetteter Bericht ist ungültig: '+e.message;}\n\nif(live){\n  $('live-days').hidden=false;$('refresh').hidden=false;$('logout').hidden=false;\n  $('example').hidden=true;$('file').closest('label').hidden=true;\n  $('days').addEventListener('change',refreshLive);$('refresh').onclick=refreshLive;\n  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshLive();});\n  refreshLive();setInterval(refreshLive,60000);\n}else if(location.hostname==='jonasbader7.github.io'&&new URLSearchParams(location.search).get('offline')!=='1'){\n  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);\n  fetch('https://jonas-portfolio-analytics.jonas-bader-analytics.workers.dev/dashboard/status',{credentials:'omit',cache:'no-store',signal:controller.signal})\n    .then(r=>{if(!r.ok)throw Error('not deployed');return r.json();})\n    .then(v=>{if(v.dashboard&&!data)location.replace('https://jonas-portfolio-analytics.jonas-bader-analytics.workers.dev/dashboard');})\n    .catch(()=>{if(!data){$('status').replaceChildren(node('span','Die automatische Live-Anbindung ist noch nicht erreichbar. Der aktualisierte Worker muss einmal bereitgestellt werden. '));const a=node('a','Live-Dashboard öffnen');a.href='https://jonas-portfolio-analytics.jonas-bader-analytics.workers.dev/dashboard';$('status').append(a);}})\n    .finally(()=>clearTimeout(timer));\n}else if(!data){$('status').textContent='Offline-Ansicht: JSON-Bericht laden oder die geschützte Live-Ansicht öffnen.';}\n</script></body></html>\n";
